import requests, itertools, json, string

URL = "http://flagchecker.chal.csaw.io:5000/check"
UA = "Mozilla/5.0"

def post(**kw):
    kw.setdefault("headers", {})
    kw["headers"].setdefault("User-Agent", UA)
    kw["timeout"] = 10
    try:
        r = requests.post(URL, **kw)
        return r.status_code, r.text.strip()[:200]
    except Exception as e:
        return None, str(e)

def body(f):
    return {"flag": f}

if __name__ == "__main__":
    print(post(data=body("test")))

