import requests
B='http://flagchecker.chal.csaw.io:5000'
H={'User-Agent':'Mozilla/5.0'}
def show(tag, r):
    print(tag, '=>', r.status_code, len(r.content), repr(r.text[:120]))

# methods
for m in ['PUT','PATCH','DELETE','TRACE','HEAD','CONNECT','PROPFIND','FOO']:
    try:
        r=requests.request(m, B+'/check', headers=H, data={'flag':'test'}, timeout=10)
        show(m, r)
    except Exception as e:
        print(m, 'ERR', str(e)[:80])

# weird paths
for path in ['/%63heck','/check%00','/./check','/check;','/check;.css','//check','/check/.','/check%2e','/check%20','/ check','/Check','/check\x00']:
    try:
        r=requests.post(B+path, headers=H, data={'flag':'test'}, timeout=10)
        show('POST '+path, r)
    except Exception as e:
        print(path, 'ERR', str(e)[:80])

# weird encodings / bodies
for ct in ['application/x-www-form-urlencoded; charset=utf-8','application/x-www-form-urlencoded; charset=latin-1','application/x-www-form-urlencoded; charset=utf-16','application/x-www-form-urlencoded; charset=bogus','multipart/form-data','application/json; charset=utf-8','text/plain; charset=utf-8','']:
    try:
        r=requests.post(B+'/check', headers={**H,'Content-Type':ct}, data=b'flag=test', timeout=10)
        show('CT '+repr(ct), r)
    except Exception as e:
        print('CT', ct, 'ERR', str(e)[:80])

# invalid utf8 body
try:
    r=requests.post(B+'/check', headers={**H,'Content-Type':'application/x-www-form-urlencoded'}, data=b'flag=\xff\xfe\x00', timeout=10)
    show('invalid utf8', r)
except Exception as e:
    print('invalid utf8 ERR', str(e)[:80])

# chunked
def chunked(body):
    import socket
    s=socket.create_connection(('flagchecker.chal.csaw.io',5000), timeout=10)
    req = b'POST /check HTTP/1.1\r\nHost: flagchecker.chal.csaw.io:5000\r\nUser-Agent: Mozilla/5.0\r\nContent-Type: application/x-www-form-urlencoded\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n'
    for i in range(0, len(body), 4):
        ch=body[i:i+4]
        req += f'{len(ch):x}\r\n'.encode()+ch+b'\r\n'
    req += b'0\r\n\r\n'
    s.sendall(req)
    data=b''
    s.settimeout(5)
    try:
        while True:
            c=s.recv(65536)
            if not c: break
            data+=c
    except Exception: pass
    s.close()
    return data
print('chunked:', chunked(b'flag=test')[-120:])

